//! Rest mode and rest recovery: the state for the current day, the recovery days after a rest
//! period, and the sleep-period history that feeds them.
//! See `docs/algorithms/metrics.md`; the vectors in the tests are generated by
//! `tools/gen_public_vectors_readiness.py`.
//!
//! A rest period is the interval `[start, end]` in UTC seconds (`end` is 0 while the
//! period is open). After it ends, up to [`MAX_RECOVERY_DAYS`] recovery days follow, during
//! which the readiness score is capped (see `readiness::recovery_run`). Everything is
//! integer arithmetic. Times treated as unsigned 64-bit (the midnight of a negative time)
//! are computed in `i128`.

pub const DAY: i64 = 86400;
pub const MAX_RECOVERY_DAYS: i64 = 7;
pub const HISTORY_SIZE: usize = 30;
pub const MODE_MAGIC0: u32 = 0x47C2_9A20;
pub const MODE_MAGIC1: u32 = 0xAB4D_3D6E;

const D: i128 = DAY as i128;

/// UTC midnight at or before `t`, with unsigned division.
fn midnight(t: i64) -> i128 {
    ((t as u64) / (DAY as u64) * (DAY as u64)) as i128
}

fn sx32(v: i128) -> i128 {
    (v as u32 as i32) as i128
}

/// the rest mode input record: start, end (0 while open), an unread field and the UTC midnight of the day
/// being scored.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct RestInput {
    pub start: i64,
    pub end: i64,
    pub unused: i64,
    pub cur_midnight: i64,
}

/// the rest mode output record without the trailing byte.
///
/// `state`: 0 normal, 1 a rest period starts today, 2 resting (`a` = whole days since the
/// first day), 3 last day of a finished period (`a` = days of rest, `b` = recovery days,
/// `c` = recovery days remaining), 4 recovering (same fields), 5 invalid input.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct RestOutput {
    pub state: u32,
    pub a: u32,
    pub b: u32,
    pub c: u32,
}

/// `(rest days D, days since the end K, recovery days
/// min(D, 7), recovery days remaining, valid)`. `D` is the whole days between the start and
/// end midnights (1 when they coincide); `K = (current midnight - end midnight - 1 day) / 1 day`
/// truncated, in 32-bit arithmetic.
fn recovery_status(
    inp: &RestInput,
    start_mid: i128,
    end_mid: i128,
) -> (i128, i128, i128, i128, bool) {
    if end_mid == 0 || start_mid == 0 || end_mid < start_mid {
        return (0, 0, 0, 0, false);
    }
    let d = if end_mid == start_mid {
        1
    } else {
        ((end_mid - start_mid) & 0xFFFF_FFFF) / D
    };
    let k = sx32(inp.cur_midnight as i128 - end_mid - D) / D;
    let d7 = d.min(MAX_RECOVERY_DAYS as i128);
    let remaining = if k > d7 { 0 } else { d7 - k.max(0) };
    (d, k, d7, remaining, true)
}

pub fn get_state(inp: &RestInput) -> RestOutput {
    let mut out = RestOutput {
        state: 5,
        ..Default::default()
    };
    let cur = inp.cur_midnight as i128;
    if cur == 0 {
        return out;
    }
    let (start, mut end) = (inp.start, inp.end);
    let start_mid = midnight(start);
    let mut end_mid = midnight(end);
    if end_mid > cur {
        end = 0;
    }
    if start_mid > cur {
        return out;
    }
    if start < 1 {
        out.state = 0;
        return out;
    }
    if end > start {
        end_mid = midnight(end);
        let st = recovery_status(inp, start_mid, end_mid);
        if cur >= end_mid + D {
            if st.1 >= st.2 {
                out.state = 0;
            } else {
                out = RestOutput {
                    state: 4,
                    a: st.0 as u32,
                    b: st.2 as u32,
                    c: st.3 as u32,
                };
            }
        } else {
            out = RestOutput {
                state: 3,
                a: st.0 as u32,
                b: st.2 as u32,
                c: st.3 as u32,
            };
        }
    } else if start > end {
        if cur >= start_mid + D {
            out.state = 2;
            out.a = (((cur - (start_mid + D)) & 0xFFFF_FFFF) / D) as u32;
        } else {
            out.state = 1;
        }
    }
    out
}

/// Whole days after the end day, 0 when either time
/// is not positive or the gap is shorter than a day.
pub fn current_recovery_day(end_mid: i64, cur_midnight: i64) -> i64 {
    if end_mid < 1 || cur_midnight < 1 {
        return 0;
    }
    let d = cur_midnight - end_mid;
    if d > 0x1517F {
        d / DAY
    } else {
        0
    }
}

/// Remaining recovery days (floored at 0).
pub fn remaining_recovery_days(day: i64, total: i64) -> i64 {
    (total - day).max(0)
}

/// The rest recovery period record: start, start midnight, start midnight plus one day,
/// end, end midnight, end midnight plus one day, end of recovery, rest days, recovery days.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Period {
    pub start: i64,
    pub start_mid: i64,
    pub start_next: i64,
    pub end: i64,
    pub end_mid: i64,
    pub end_next: i64,
    pub recovery_end: i64,
    pub days: i32,
    pub recovery_days: i32,
}

/// Durations of a computed period: `(rest days, recovery days)`.
pub fn durations(p: &Period) -> (i64, i64) {
    let days = ((p.end_mid - p.start_mid) / DAY).max(0);
    let d = if p.end_mid != p.start_mid { days } else { 1 };
    (d, d.min(MAX_RECOVERY_DAYS))
}

pub fn calculate_all_times(start: i64, end: i64) -> Period {
    let mut p = Period::default();
    if start < 1 {
        return p;
    }
    p.start = start;
    p.start_mid = midnight(start) as i64;
    p.start_next = p.start_mid + DAY;
    p.end = end;
    if end < 1 {
        return p;
    }
    p.end_mid = midnight(end) as i64;
    p.end_next = p.end_mid + DAY;
    let mut d = ((p.end_mid - p.start_mid) / DAY).max(0);
    if p.end_mid == p.start_mid {
        d = 1;
    }
    let d7 = d.min(MAX_RECOVERY_DAYS);
    p.days = d as i32;
    p.recovery_days = d7 as i32;
    p.recovery_end = p.end_next + d7 * DAY;
    p
}

/// The state of a stored period at time `now`.
pub fn past_state(period: &Period, now: i64) -> RestOutput {
    let mut out = RestOutput {
        state: 5,
        ..Default::default()
    };
    if period.start < 1 || now < 1 || period.end < 1 {
        return out;
    }
    if period.recovery_end < now {
        out.state = 0;
        return out;
    }
    let now_mid = midnight(now) as i64;
    if period.end_mid >= now {
        if period.start_next >= now {
            out.state = if period.start_mid >= now { 0 } else { 1 };
        } else {
            out.state = 2;
            out.a = (((now_mid - period.start_next) as u64 & 0xFFFF_FFFF) / DAY as u64) as u32;
        }
        return out;
    }
    out.state = if period.end_next < now { 4 } else { 3 };
    out.a = period.days as u32;
    out.b = period.recovery_days as u32;
    let gap = now_mid - period.end_next;
    let k = if gap > 0x1517F { gap / DAY } else { 0 };
    out.c = (period.recovery_days as i64 - k).max(0) as u32;
    out
}

/// The 30-entry period history.
#[derive(Clone, Debug, Default)]
pub struct History {
    pub valid: bool,
    pub periods: Vec<Period>,
}

impl History {
    /// `raw` holds `(start, end)` pairs; `None`
    /// invalidates the history.
    pub fn set(&mut self, raw: Option<&[(i64, i64)]>, count: u32) {
        self.valid = false;
        self.periods.clear();
        let Some(raw) = raw else { return };
        self.valid = true;
        let n = ((count & 0xFFFF) as usize).min(HISTORY_SIZE);
        for &(s, e) in raw.iter().take(n) {
            self.periods.push(calculate_all_times(s, e));
        }
    }

    /// The newest period that contains `t`, from its start
    /// to the end of its recovery (an open period contains every later time).
    pub fn find(&self, t: i64) -> Option<&Period> {
        for p in self.periods.iter().rev() {
            if p.end == 0 {
                if p.start <= t {
                    return Some(p);
                }
                continue;
            }
            if p.start > t || p.recovery_end < t {
                continue;
            }
            return Some(p);
        }
        None
    }

    pub fn status_for_activity(&self, t: i64) -> RestOutput {
        if t < 1 || !self.valid {
            return RestOutput {
                state: 5,
                ..Default::default()
            };
        }
        let Some(p) = self.find(t) else {
            return RestOutput::default();
        };
        if p.end != 0 {
            return past_state(p, t);
        }
        get_state(&RestInput {
            start: p.start,
            end: p.end,
            unused: 0,
            cur_midnight: midnight(t) as i64,
        })
    }
}

/// the rest mode state: magic, state byte, rest-day count `n`, `total`, `remaining`, magic.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Mode {
    pub magic0: u32,
    pub state: u8,
    pub n: u32,
    pub total: u32,
    pub remaining: u32,
    pub magic1: u32,
}

impl Default for Mode {
    fn default() -> Self {
        Mode {
            magic0: MODE_MAGIC0,
            state: 0,
            n: 0,
            total: 0,
            remaining: 0,
            magic1: MODE_MAGIC1,
        }
    }
}

impl Mode {
    pub fn sane(&self) -> bool {
        self.magic0 == MODE_MAGIC0
            && self.magic1 == MODE_MAGIC1
            && self.n < 0x1C85
            && self.total < 8
            && self.remaining < 8
            && self.state < 5
    }

    fn clear(&mut self) {
        self.n = 0;
        self.total = 0;
        self.remaining = 0;
    }

    /// Apply a ring rest-mode event (header 0xfe 0x20 or
    /// 0xfe 0x21, u16 LE length at 2, payload from 4). 0xfe20 starts a rest period (state 1)
    /// from state 0, 3 or 4; 0xfe21 ends it (byte 12 set keeps the state at 3, recovering).
    /// Returns the status code: 0 ok, 4 unknown event, 9 short event.
    pub fn process_event(&mut self, ev: &[u8]) -> i32 {
        let tag = if ev.len() >= 2 {
            (ev[0] as u32) << 8 | ev[1] as u32
        } else {
            0
        };
        let ln = if ev.len() >= 4 {
            ev[2] as usize | (ev[3] as usize) << 8
        } else {
            0
        };
        match tag {
            0xFE21 => {
                if ln < 9 {
                    return 9;
                }
                let flag = if 12 < ln + 4 && ev.len() > 12 {
                    ev[12]
                } else {
                    0
                };
                match self.state {
                    2 => {
                        self.total = self.n.min(7);
                        self.remaining = self.total;
                        self.state = 3;
                    }
                    1 => {
                        self.clear();
                        self.state = if flag != 0 { 3 } else { 0 };
                    }
                    0 => self.clear(),
                    _ => {}
                }
                0
            }
            0xFE20 => {
                if ln < 8 {
                    return 9;
                }
                if self.state <= 4 && (1u32 << self.state) & 0x19 != 0 {
                    self.clear();
                    self.state = 1;
                }
                0
            }
            _ => 4,
        }
    }

    /// A main sleep ended. While resting the rest-day
    /// count grows by `n` (at least 1); while recovering the remaining days drop by `n` (at
    /// least 1).
    pub fn major_sleep_period(&mut self, n: u32) {
        let step = n.max(1);
        match self.state {
            1 => self.state = 2,
            2 => {
                self.n += step;
                self.state = 2;
            }
            3 => self.state = 4,
            4 if self.remaining > step => {
                self.remaining -= step;
                self.state = 4;
            }
            _ => {
                self.clear();
                self.state = 0;
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn open_period_states() {
        let cur = 1_760_054_400; // a UTC midnight
        let s = |start| {
            get_state(&RestInput {
                start,
                end: 0,
                unused: 0,
                cur_midnight: cur,
            })
            .state
        };
        assert_eq!(s(cur + 10), 1);
        assert_eq!(s(cur - 3 * DAY + 10), 2);
        assert_eq!(s(0), 0);
    }

    macro_rules! vector_tests {
        () => {
            #[test]
            fn get_state_matches_reference() {
                for (i, &(s, e, cur, want)) in STATE_VECTORS.iter().enumerate() {
                    let got = get_state(&RestInput {
                        start: s,
                        end: e,
                        unused: 0,
                        cur_midnight: cur,
                    });
                    assert_eq!(
                        [got.state, got.a, got.b, got.c],
                        want,
                        "case {i}: {s} {e} {cur}"
                    );
                }
            }

            #[test]
            fn times_match_reference() {
                for (i, &(s, e, want_p, now, want_past, want_dur)) in TIMES_VECTORS.iter().enumerate() {
                    let p = calculate_all_times(s, e);
                    let got = [
                        p.start,
                        p.start_mid,
                        p.start_next,
                        p.end,
                        p.end_mid,
                        p.end_next,
                        p.recovery_end,
                        p.days as i64,
                        p.recovery_days as i64,
                    ];
                    assert_eq!(got, want_p, "case {i}: calculate_all_times({s}, {e})");
                    let g = past_state(&p, now);
                    assert_eq!(
                        [g.state, g.a, g.b, g.c],
                        want_past,
                        "case {i}: past_state at {now}"
                    );
                    assert_eq!(durations(&p), want_dur, "case {i}: durations");
                }
            }

            #[test]
            fn history_matches_reference() {
                for (i, &(periods, use_null, count, queries)) in HISTORY_VECTORS.iter().enumerate() {
                    let mut h = History::default();
                    h.set(if use_null { None } else { Some(periods) }, count);
                    for &(q, want) in queries {
                        let g = h.status_for_activity(q);
                        assert_eq!([g.state, g.a, g.b, g.c], want, "case {i}: query {q}");
                    }
                }
            }

            #[test]
            fn event_machine_matches_reference() {
                for (i, (steps, want_sane)) in MACHINE_VECTORS.iter().enumerate() {
                    let mut m = Mode::default();
                    for (j, &(event, k, want_ret, want)) in steps.iter().enumerate() {
                        let ret = match event {
                            Some(ev) => m.process_event(ev),
                            None => {
                                m.major_sleep_period(k);
                                0
                            }
                        };
                        assert_eq!(ret, want_ret, "case {i} step {j}");
                        assert_eq!(
                            (m.state, m.n, m.total, m.remaining),
                            want,
                            "case {i} step {j}"
                        );
                    }
                    assert_eq!(m.sane(), *want_sane, "case {i} sanity");
                }
            }
        };
    }

    mod python_port {
        use super::*;
        include!("vectors/rest_recovery.rs");
        vector_tests!();
    }

}
